// ---- domain types (match the FastAPI response shapes in koomsure-backend) ----
interface Listing {
  platform: string;
  shop_name: string;
  net_price: number | null;
  price_change: number | null;
  coupon: number;
  shipping: number | null;
  in_stock: boolean;
  url: string;
}

interface Product {
  product_id: string;
  brand: string;
  model_number: string;
  product_name: string;
  image: string;
  specs: string;
  listings: Listing[];
}

interface PriceHistoryEntry {
  platform: string;
  date: string;
  price: number;
}

interface ListingDetails {
  currentPrice: number | null;
  originalPrice: number | null;
  discountPct: number;
  coupon: number;
  totalPrice: number | null;
}

// A compare-table row: one listing merged with its derived price breakdown + ranking flag.
interface CompareRow extends Listing, ListingDetails {
  isCheapest: boolean;
}

// Deal-dashboard card data - "discount" mode uses original_price/discount_pct,
// "drop" mode uses previous_price/drop_amount/drop_pct (see DealCard's `mode` prop).
interface Deal {
  product_id: string;
  product_name: string;
  image: string;
  platform: string;
  current_price: number;
  url: string;
  original_price?: number;
  discount_pct?: number;
  previous_price?: number;
  drop_amount?: number;
  drop_pct?: number;
}

