// ============================================================================
// FEATURE: กราฟราคาย้อนหลัง + ตารางเปรียบเทียบราคา
// ============================================================================
// ราคาย้อนหลังตอนนี้มาจากตาราง price_history จริงใน Postgres ผ่าน GET /api/products/:id/price-history
// (ดู fetchPriceHistory ด้านล่าง) ไม่ได้ฝัง mock log ไว้ในไฟล์นี้อีกต่อไป

// STEP 2: แปลง log แบบ flat (1 แถว = 1 แพลตฟอร์ม 1 วัน) ให้เป็นรูปแบบที่ Recharts ใช้ได้
// คือ array ของ { date, [ชื่อแพลตฟอร์ม1]: ราคา, [ชื่อแพลตฟอร์ม2]: ราคา, ... } เรียงตามวันที่
interface ChartDataRow {
  date: string;
  [platform: string]: string | number | null;
}

function buildChartData(historyEntries: PriceHistoryEntry[]): ChartDataRow[] {
  const dates = [...new Set(historyEntries.map((e) => e.date))].sort();
  const platforms = [...new Set(historyEntries.map((e) => e.platform))];
  return dates.map((date) => {
    const row: ChartDataRow = { date };
    platforms.forEach((platform) => {
      const match = historyEntries.find((e) => e.date === date && e.platform === platform);
      row[platform] = match ? match.price : null; // null = วันนั้นไม่มีข้อมูลของแพลตฟอร์มนี้ Recharts จะเว้นช่วงเส้นให้เอง
    });
    return row;
  });
}

// STEP 3: เช็คว่าข้อมูลย้อนหลัง "พอ" จะพล็อตกราฟที่มีความหมายหรือยัง (ต้องมีอย่างน้อย 2 วันที่ต่างกัน)
function hasEnoughHistory(historyEntries: PriceHistoryEntry[]): boolean {
  if (!historyEntries || historyEntries.length === 0) return false;
  const distinctDates = new Set(historyEntries.map((e) => e.date));
  return distinctDates.size >= 2;
}

function fmtDateShort(dateStr: string) {
  const d = new Date(dateStr);
  return d.toLocaleDateString("th-TH", { day: "numeric", month: "short" });
}

// STEP 4: คำนวณ "ราคาปัจจุบัน", "ราคาเดิม", "%ลด" และ "ราคารวม" จากข้อมูลที่มีอยู่แล้วใน listing
// (net_price = ราคาสุทธิหลังหักคูปอง+บวกค่าส่ง ที่ทีม Data ส่งมา, price_change = ปัจจุบัน - เดิม)
// current_price = net_price - shipping + coupon  →  ย้อนกลับสมการ "สุทธิ = ปัจจุบัน - คูปอง + ค่าส่ง"
function deriveListingDetails(listing: Listing): ListingDetails {
  const shipping = listing.shipping ?? 0;
  const coupon = listing.coupon ?? 0;
  const hasPrice = listing.net_price !== null && listing.net_price !== undefined;
  if (!hasPrice) {
    return { currentPrice: null, originalPrice: null, discountPct: 0, coupon: 0, totalPrice: null };
  }
  // currentPrice = "ราคาปัจจุบัน" ที่ป้ายราคาบนหน้าร้าน ก่อนหักคูปอง (ย้อนสมการ: สุทธิ = ปัจจุบัน - คูปอง + ค่าส่ง)
  const currentPrice = listing.net_price! - shipping + coupon;
  const originalPrice = currentPrice - (listing.price_change ?? 0);
  // %ลด คำนวณจาก "ราคาป้าย" (ปัจจุบัน vs เดิม) เท่านั้น ไม่เกี่ยวกับคูปองเลย - คูปองแสดงแยกเป็นคอลัมน์ของตัวเองแทน
  // (พิสูจน์ด้วยตัวเลขจริงแล้วว่าค่านี้ตรงกับ %ลด ในข้อมูลดิบเป๊ะๆ ไม่ว่าคูปองจะเยอะแค่ไหนก็ไม่กระทบตัวเลขนี้)
  const discountPct = originalPrice > 0 ? Math.max(0, (-(listing.price_change ?? 0) / originalPrice) * 100) : 0;
  // BUG เดิม: totalPrice เคยคำนวณจาก currentPrice (ราคาก่อนหักคูปอง) + ค่าส่ง ทำให้ "ราคารวม" ในตารางนี้
  // ไม่ตรงกับราคาสุทธิ (net_price) ที่ใช้จัดอันดับ Best Value ทุกที่อื่นในแอป
  // net_price มีค่าส่งบวกรวมอยู่แล้วตั้งแต่ต้น (สมการ: สุทธิ = ปัจจุบัน - คูปอง + ค่าส่ง) ดังนั้น "ราคารวม" ที่ถูกต้อง
  // คือ net_price ตรงๆ (ถ้าบวกค่าส่งซ้ำอีกทีจะนับค่าส่งซ้ำสองรอบ) ให้สอดคล้องกับ bestValuePrice() ที่ใช้ทั้งแอป
  const totalPrice = listing.net_price;
  return { currentPrice, originalPrice, discountPct, coupon, totalPrice };
}

// ============================================================================
// STEP 5: จำลอง REST API layer (สอดคล้องกับ endpoint ที่ระบุในโจทย์)
// GET /api/products/:productId/price-history   →  fetchPriceHistory(productId)
// GET /api/products/:productId/compare         →  fetchCompareData(productId)
// ในสภาพแวดล้อม Artifacts นี้ไม่มี Express server รันอยู่จริง จึงจำลองด้วย Promise + delay
// เพื่อให้ Loading state / error handling ทำงานเหมือนเรียก API จริง แต่ไปอ่านข้อมูลที่ฝังในแอปแทน
// ตอน deploy จริง ให้เปลี่ยน resolve(...) เป็น fetch(`/api/products/${productId}/price-history`).then(r => r.json())
// (ดูตัวอย่าง Express endpoint คู่กันได้ในไฟล์ server.js ที่แนบมาด้วย)
const API_BASE = "http://localhost:8000"; // ตอน deploy จริงเปลี่ยนเป็น URL ของ backend จริง

// รูปสินค้าจาก backend เป็น relative path เช่น "/static/products/P001.jpg" (เดิมเคยเป็น base64 data URI
// ฝังมากับข้อมูลเลยจึงไม่เคยมีปัญหานี้) ต้องต่อ API_BASE ให้เต็มก่อน ไม่งั้น browser จะ resolve path นี้
// เทียบกับ origin ของหน้าเว็บ (localhost:5173) แทนที่จะเป็น backend (localhost:8000) ทำให้รูปหายไปหมด
function resolveImageUrl(path: string | null | undefined): string | undefined {
  if (!path) return undefined;
  if (path.startsWith("http://") || path.startsWith("https://") || path.startsWith("data:")) return path;
  return `${API_BASE}${path}`;
}

function fetchPriceHistory(productId: string): Promise<PriceHistoryEntry[]> {
  return fetch(`${API_BASE}/api/products/${productId}/price-history`).then((r) => {
    if (!r.ok) throw new Error("โหลดราคาย้อนหลังไม่สำเร็จ");
    return r.json() as Promise<PriceHistoryEntry[]>;
  });
}

function fetchCompareData(productId: string): Promise<CompareRow[]> {
  return fetch(`${API_BASE}/api/products/${productId}/compare`)
    .then((r) => {
      if (!r.ok) throw new Error("โหลดข้อมูลเปรียบเทียบราคาไม่สำเร็จ");
      return r.json() as Promise<Listing[]>;
    })
    .then((listings) => {
      // logic คำนวณ isCheapest ยังทำฝั่ง frontend เหมือนเดิม (ตัว backend ส่งแค่ราคาดิบมาให้)
      const rows: CompareRow[] = listings.map((listing) => ({
        ...listing,
        ...deriveListingDetails(listing),
        isCheapest: false,
      }));
      const eligible = rows.filter((r) => r.in_stock !== false && r.totalPrice !== null);
      const cheapestTotal = eligible.length ? Math.min(...eligible.map((r) => r.totalPrice as number)) : null;
      return rows.map((r) => ({
        ...r,
        isCheapest: cheapestTotal !== null && r.in_stock !== false && r.totalPrice === cheapestTotal,
      }));
    });
}

// STEP 6: กราฟเส้นราคาย้อนหลัง แยกสีตามแพลตฟอร์ม (ใช้สีเดียวกับ PLATFORM_STYLE ให้สอดคล้องกับที่อื่นในแอป)
interface PriceHistoryState {
  status: "loading" | "success" | "error";
  data: PriceHistoryEntry[];
}

function PriceHistoryChart({ productId }: { productId: string }) {
  const [state, setState] = useState<PriceHistoryState>({ status: "loading", data: [] });

  useEffect(() => {
    let cancelled = false;
    setState({ status: "loading", data: [] });
    fetchPriceHistory(productId)
      .then((entries) => {
        if (cancelled) return;
        setState({ status: "success", data: entries });
      })
      .catch(() => {
        if (cancelled) return;
        setState({ status: "error", data: [] });
      });
    return () => {
      cancelled = true;
    };
  }, [productId]);

  if (state.status === "loading") {
    return (
      <div className="flex h-56 animate-pulse flex-col items-center justify-center gap-2 rounded-2xl" style={{ background: T.bgVia }}>
        <TrendingUp size={22} style={{ color: T.inkSoft }} />
        <span className="text-xs font-medium" style={{ color: T.inkSoft }}>
          กำลังโหลดกราฟราคาย้อนหลัง...
        </span>
      </div>
    );
  }

  if (state.status === "error") {
    return (
      <div className="flex h-40 flex-col items-center justify-center gap-2 rounded-2xl text-center" style={{ background: T.bgVia }}>
        <AlertCircle size={20} style={{ color: T.red }} />
        <span className="text-xs font-medium" style={{ color: T.inkSoft }}>
          โหลดข้อมูลราคาย้อนหลังไม่สำเร็จ ลองใหม่อีกครั้ง
        </span>
      </div>
    );
  }

  if (!hasEnoughHistory(state.data)) {
    return (
      <div className="flex h-40 flex-col items-center justify-center gap-2 rounded-2xl text-center" style={{ background: T.bgVia }}>
        <TrendingUp size={20} style={{ color: T.inkSoft }} />
        <span className="px-4 text-xs font-medium" style={{ color: T.inkSoft }}>
          ยังไม่มีข้อมูลย้อนหลังเพียงพอ ระบบจะเก็บสถิติเพิ่มขึ้นทุกครั้งที่ scraper รัน
        </span>
      </div>
    );
  }

  const chartData = buildChartData(state.data);
  const platforms = [...new Set(state.data.map((e) => e.platform))];

  return (
    <div className="rounded-2xl p-3" style={{ background: T.bgVia }}>
      <ResponsiveContainer width="100%" height={220}>
        <LineChart data={chartData} margin={{ top: 8, right: 12, left: 0, bottom: 0 }}>
          <CartesianGrid strokeDasharray="3 3" stroke={T.blueLine} />
          <XAxis dataKey="date" tickFormatter={fmtDateShort} tick={{ fontSize: 11, fill: T.inkSoft }} />
          <YAxis
            tickFormatter={(v) => `฿${fmtBaht(v)}`}
            tick={{ fontSize: 11, fill: T.inkSoft }}
            width={64}
            domain={["dataMin - 200", "dataMax + 200"]}
          />
          <Tooltip
            formatter={(value) => (value === null || value === undefined ? "ไม่มีข้อมูล" : `฿${fmtBaht(Number(value))}`)}
            labelFormatter={(label) => fmtDateShort(String(label))}
            contentStyle={{ borderRadius: 12, border: `1px solid ${T.blueLine}`, fontSize: 12 }}
          />
          <Legend wrapperStyle={{ fontSize: 11 }} />
          {platforms.map((platform) => (
            <Line
              key={platform}
              type="monotone"
              dataKey={platform}
              stroke={(PLATFORM_STYLE[platform] || {}).fg || T.inkSoft}
              strokeWidth={2.5}
              dot={{ r: 3 }}
              connectNulls
            />
          ))}
        </LineChart>
      </ResponsiveContainer>
    </div>
  );
}

// STEP 7: ตารางเปรียบเทียบราคาใต้กราฟ ตามคอลัมน์ที่โจทย์ระบุ
interface CompareState {
  status: "loading" | "success" | "error";
  rows: CompareRow[];
}

function CompareTable({ productId }: { productId: string }) {
  const [state, setState] = useState<CompareState>({ status: "loading", rows: [] });

  useEffect(() => {
    let cancelled = false;
    setState({ status: "loading", rows: [] });
    fetchCompareData(productId)
      .then((rows) => {
        if (cancelled) return;
        setState({ status: "success", rows });
      })
      .catch(() => {
        if (cancelled) return;
        setState({ status: "error", rows: [] });
      });
    return () => {
      cancelled = true;
    };
  }, [productId]);

  if (state.status === "loading") {
    return (
      <div className="flex flex-col gap-2">
        {[0, 1, 2].map((i) => (
          <div key={i} className="h-12 animate-pulse rounded-xl" style={{ background: T.bgVia }} />
        ))}
      </div>
    );
  }

  if (state.status === "error" || state.rows.length === 0) {
    return (
      <div className="flex h-24 items-center justify-center rounded-2xl text-center text-xs font-medium" style={{ background: T.bgVia, color: T.inkSoft }}>
        {state.status === "error" ? "โหลดตารางเปรียบเทียบไม่สำเร็จ ลองใหม่อีกครั้ง" : "ไม่มีข้อมูลร้านค้าสำหรับสินค้านี้"}
      </div>
    );
  }

  // ร้านหมดสต๊อกให้จมไปอยู่ล่างสุดเสมอ เหมือนตรรกะเดิมของแอป
  const sortedRows = [...state.rows].sort((a, b) => {
    const aOut = a.in_stock === false || a.currentPrice === null;
    const bOut = b.in_stock === false || b.currentPrice === null;
    if (aOut && !bOut) return 1;
    if (!aOut && bOut) return -1;
    return (a.totalPrice ?? Infinity) - (b.totalPrice ?? Infinity);
  });

  return (
    <div className="overflow-x-auto rounded-2xl" style={{ border: `1px solid ${T.blueLine}` }}>
      <table className="w-full min-w-[560px] border-collapse text-left text-xs sm:text-sm">
        <thead>
          <tr style={{ background: T.bgVia }}>
            {["แพลตฟอร์ม", "ราคาปัจจุบัน", "ราคาเดิม", "%ลด", "คูปอง", "ค่าส่ง", "ราคารวม", ""].map((h) => (
              <th key={h} className="whitespace-nowrap px-3 py-2.5 font-bold" style={{ color: T.inkStrong }}>
                {h}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {sortedRows.map((row) => {
            const isOut = row.in_stock === false || row.currentPrice === null;
            const platform = PLATFORM_STYLE[row.platform] || { bg: "#eee", fg: "#333" };
            return (
              <tr
                key={row.platform + row.shop_name}
                style={{
                  background: row.isCheapest ? T.peach : "transparent",
                  opacity: isOut ? 0.55 : 1,
                  borderTop: `1px solid ${T.blueLine}`,
                }}
              >
                <td className="whitespace-nowrap px-3 py-2.5">
                  <span
                    className="rounded-full px-2 py-1 text-[11px] font-bold"
                    style={{ background: platform.bg, color: platform.fg }}
                  >
                    {row.platform}
                  </span>
                  {row.isCheapest && (
                    <span className="ml-1.5 text-[11px] font-bold" style={{ color: T.peachText }}>
                      ★ ถูกที่สุด
                    </span>
                  )}
                </td>
                <td className="whitespace-nowrap px-3 py-2.5 font-semibold" style={{ color: T.inkStrong }}>
                  {isOut ? "-" : `฿${fmtBaht(row.currentPrice ?? 0)}`}
                </td>
                <td className="whitespace-nowrap px-3 py-2.5" style={{ color: T.inkSoft }}>
                  {isOut ? "-" : `฿${fmtBaht(row.originalPrice ?? 0)}`}
                </td>
                <td className="whitespace-nowrap px-3 py-2.5" style={{ color: isOut ? T.inkSoft : T.green }}>
                  {isOut || row.discountPct <= 0 ? "-" : `-${row.discountPct.toFixed(0)}%`}
                </td>
                <td className="whitespace-nowrap px-3 py-2.5" style={{ color: isOut ? T.inkSoft : T.pinkText }}>
                  {isOut || !row.coupon ? "-" : `-฿${fmtBaht(row.coupon)}`}
                </td>
                <td className="whitespace-nowrap px-3 py-2.5" style={{ color: T.inkSoft }}>
                  {isOut ? "-" : row.shipping ? `฿${fmtBaht(row.shipping)}` : "ฟรี"}
                </td>
                <td className="whitespace-nowrap px-3 py-2.5 font-bold" style={{ fontFamily: "'Fraunces', serif", color: T.inkStrong }}>
                  {isOut ? "-" : `฿${fmtBaht(row.totalPrice ?? 0)}`}
                </td>
                <td className="whitespace-nowrap px-3 py-2.5">
                  {isOut ? (
                    <span className="rounded-full px-3 py-1.5 text-xs font-bold" style={{ background: "#E2E5EA", color: "#9AA3B2" }}>
                      หมดสต๊อก
                    </span>
                  ) : (
                    <a
                      href={row.url}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="inline-flex items-center gap-1 rounded-full px-3 py-1.5 text-xs font-bold transition-colors duration-150"
                      style={{ background: T.blue, color: T.inkStrong }}
                    >
                      ไปที่ร้านค้า
                      <ExternalLink size={12} />
                    </a>
                  )}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

// ============================================================================
// FEATURE: Top Deal Dashboard (หน้าแรก)
// ============================================================================
// ทั้งสอง endpoint คำนวณจากข้อมูลจริงใน Postgres ฝั่ง backend แล้ว (products/listings/coupons
// สำหรับ top-discount, price_history สำหรับ price-drop) ดู koomsure-backend/src/koom_sure_backend/api/services/deals
// price-drop จะเป็น array ว่างจนกว่าจะมีสแนปช็อตราคาสะสมอย่างน้อย 2 รอบต่อสินค้า+แพลตฟอร์ม - เป็นสถานะที่ถูกต้องจริง ไม่ใช่บั๊ก
function fetchTopDiscountDeals(limit = 10): Promise<Deal[]> {
  return fetch(`${API_BASE}/api/deals/top-discount?limit=${limit}`).then((r) => {
    if (!r.ok) throw new Error("โหลดดีลลดแรงสุดไม่สำเร็จ");
    return r.json() as Promise<Deal[]>;
  });
}

function fetchPriceDropDeals(limit = 10): Promise<Deal[]> {
  return fetch(`${API_BASE}/api/deals/price-drop?limit=${limit}`).then((r) => {
    if (!r.ok) throw new Error("โหลดดีลราคาตกไม่สำเร็จ");
    return r.json() as Promise<Deal[]>;
  });
}

// STEP 4: การ์ดดีลเดี่ยว - รูป, ชื่อสินค้า, แพลตฟอร์ม, ราคาปัจจุบัน+ราคาเดิมขีดฆ่า, badge %ลด/จำนวนที่ลด
function DealCard({
  deal,
  mode,
  onOpenProduct,
}: {
  deal: Deal;
  mode: "discount" | "drop";
  onOpenProduct: (product: Product) => void;
}) {
  const platform = PLATFORM_STYLE[deal.platform] || { bg: "#eee", fg: "#333" };
  const product = PRODUCTS.find((p) => p.product_id === deal.product_id);

  const badgeText =
    mode === "discount" ? `-${Math.round(deal.discount_pct ?? 0)}%` : `-฿${fmtBaht(Math.round(deal.drop_amount ?? 0))}`;

  return (
    <div
      className="flex flex-col overflow-hidden rounded-3xl transition-all duration-300 ease-out"
      style={{ background: T.paper, border: `1px solid ${T.blueLine}`, boxShadow: "0 10px 24px -14px rgba(148,116,196,0.28)" }}
      onMouseEnter={(e) => (e.currentTarget.style.transform = "translateY(-4px)")}
      onMouseLeave={(e) => (e.currentTarget.style.transform = "translateY(0)")}
    >
      <div className="relative" style={{ background: T.paper }}>
        {deal.image ? (
          <img src={resolveImageUrl(deal.image)} alt={deal.product_name} className="h-36 w-full object-contain p-5" />
        ) : (
          <div className="flex h-36 w-full items-center justify-center text-xs" style={{ background: T.bgVia, color: T.inkSoft }}>
            ไม่มีรูปสินค้า
          </div>
        )}
        <span
          className="absolute left-3 top-3 rounded-full px-2.5 py-1 text-xs font-extrabold shadow-sm"
          style={{ background: T.pinkHeart, color: "#FFFFFF" }}
        >
          {badgeText}
        </span>
      </div>

      <div className="flex flex-1 flex-col gap-2 px-4 py-4">
        <span
          className="w-fit rounded-full px-2 py-0.5 text-[11px] font-bold"
          style={{ background: platform.bg, color: platform.fg }}
        >
          {deal.platform}
        </span>
        <span className="line-clamp-2 text-sm font-semibold leading-snug" style={{ color: T.inkStrong }}>
          {deal.product_name}
        </span>

        <div className="mt-1 flex items-baseline gap-2">
          <span style={{ fontFamily: "'Fraunces', serif", color: T.pinkText }} className="text-lg font-bold">
            ฿{fmtBaht(Math.round(deal.current_price))}
          </span>
          <span className="text-xs line-through" style={{ color: T.inkSoft }}>
            ฿{fmtBaht(Math.round((mode === "discount" ? deal.original_price : deal.previous_price) ?? 0))}
          </span>
        </div>

        <button
          onClick={() => product && onOpenProduct(product)}
          disabled={!product}
          className="mt-2 flex items-center justify-center gap-1.5 rounded-full px-3.5 py-2.5 text-xs font-bold transition-colors duration-200 disabled:cursor-not-allowed disabled:opacity-50 sm:py-2"
          style={{ background: T.blue, color: T.inkStrong }}
        >
          ดูราคาเปรียบเทียบ
          <ExternalLink size={13} />
        </button>
      </div>
    </div>
  );
}

interface DealsState {
  status: "loading" | "success" | "error";
  deals: Deal[];
}

// STEP 5: Dashboard หลัก - แท็บสลับ "ลดแรงสุด" / "ราคาตกล่าสุด" + grid การ์ด + loading/empty state
function TopDealDashboard({ onOpenProduct }: { onOpenProduct: (product: Product) => void }) {
  const [tab, setTab] = useState("discount"); // "discount" | "drop"
  const [state, setState] = useState<DealsState>({ status: "loading", deals: [] });

  useEffect(() => {
    let cancelled = false;
    setState({ status: "loading", deals: [] });
    const fetcher = tab === "discount" ? fetchTopDiscountDeals(10) : fetchPriceDropDeals(10);
    fetcher
      .then((deals) => {
        if (cancelled) return;
        setState({ status: "success", deals });
      })
      .catch(() => {
        if (cancelled) return;
        setState({ status: "error", deals: [] });
      });
    return () => {
      cancelled = true;
    };
  }, [tab]);

  return (
    <section className="mb-8">
      <div className="mb-4 flex flex-wrap items-center justify-between gap-3">
        <h2 className="flex items-center gap-1.5 text-lg font-bold" style={{ color: T.inkStrong }}>
          <TrendingUp size={18} style={{ color: T.pinkText }} />
          ดีลเด็ดวันนี้
        </h2>
        <div className="flex gap-2">
          {[
            { id: "discount", label: "ลดแรงสุด" },
            { id: "drop", label: "ราคาตกล่าสุด" },
          ].map((t) => {
            const active = tab === t.id;
            return (
              <button
                key={t.id}
                onClick={() => setTab(t.id)}
                className="rounded-full px-4 py-2 text-sm font-bold transition-colors duration-150 sm:py-1.5 sm:text-xs"
                style={{
                  background: active ? T.pinkHeart : T.paper,
                  color: active ? "#FFFFFF" : T.inkStrong,
                  border: `1px solid ${active ? T.pinkHeart : T.blueLine}`,
                }}
              >
                {t.label}
              </button>
            );
          })}
        </div>
      </div>

      {state.status === "loading" && (
        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
          {[0, 1, 2, 3].map((i) => (
            <div key={i} className="h-64 animate-pulse rounded-3xl" style={{ background: T.bgVia }} />
          ))}
        </div>
      )}

      {state.status === "error" && (
        <div className="rounded-3xl border border-dashed py-12 text-center text-sm" style={{ borderColor: T.blueLine, color: T.inkSoft }}>
          โหลดดีลไม่สำเร็จ ลองใหม่อีกครั้ง
        </div>
      )}

      {state.status === "success" && state.deals.length === 0 && (
        <div className="rounded-3xl border border-dashed py-12 text-center text-sm" style={{ borderColor: T.blueLine, color: T.inkSoft }}>
          {tab === "discount"
            ? "ยังไม่มีดีลลดราคาในตอนนี้ ลองกลับมาเช็คใหม่อีกครั้ง"
            : "ยังไม่มีข้อมูลเพียงพอ ระบบต้องเก็บราคาซ้ำอย่างน้อย 2 รอบถึงจะรู้ว่าราคาตกลงมั้ย 🌱"}
        </div>
      )}

      {state.status === "success" && state.deals.length > 0 && (
        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
          {state.deals.map((deal) => (
            <DealCard key={deal.product_id + deal.platform} deal={deal} mode={tab === "discount" ? "discount" : "drop"} onOpenProduct={onOpenProduct} />
          ))}
        </div>
      )}
    </section>
  );
}

function FavoriteHeart({
  active,
  onToggle,
  size = 18,
  floating = true,
}: {
  active: boolean;
  onToggle: () => void;
  size?: number;
  floating?: boolean;
}) {
  const [bounce, setBounce] = useState(false);

  const handleClick = (e: ReactMouseEvent) => {
    e.stopPropagation();
    onToggle();
    setBounce(true);
    setTimeout(() => setBounce(false), 420);
  };

  return (
    <button
      onClick={handleClick}
      aria-label="รายการโปรด"
      aria-pressed={active}
      className={
        floating
          ? "absolute right-3 top-3 flex h-10 w-10 items-center justify-center rounded-full transition-transform duration-150 hover:scale-110 sm:h-9 sm:w-9"
          : "flex h-10 w-10 items-center justify-center rounded-full transition-transform duration-150 hover:scale-110 sm:h-9 sm:w-9"
      }
      style={{
        background: active ? T.pink : "rgba(255,255,255,0.85)",
        backdropFilter: "blur(4px)",
        boxShadow: "0 2px 8px rgba(51,65,85,0.12)",
      }}
    >
      <Heart
        size={size}
        strokeWidth={2.2}
        fill={active ? T.pinkHeart : "none"}
        color={active ? T.pinkHeart : T.inkSoft}
        style={{
          transform: bounce ? "scale(1.35)" : "scale(1)",
          transition: "transform 220ms cubic-bezier(.34,1.56,.64,1)",
        }}
      />
    </button>
  );
}

function ProductCard({
  product,
  onOpen,
  isFavorite,
  onToggleFavorite,
}: {
  product: Product;
  onOpen: (product: Product) => void;
  isFavorite: boolean;
  onToggleFavorite: (productId: string) => void;
}) {
  return (
    <div
      role="button"
      tabIndex={0}
      onClick={() => onOpen(product)}
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") onOpen(product);
      }}
      className="group flex cursor-pointer flex-col overflow-hidden rounded-3xl text-left outline-none transition-all duration-300 ease-out"
      style={{ background: T.paper, border: `1px solid ${T.blueLine}`, boxShadow: "0 10px 28px -14px rgba(148,116,196,0.28)" }}
      onMouseEnter={(e) => {
        e.currentTarget.style.transform = "translateY(-6px)";
        e.currentTarget.style.boxShadow = "0 22px 36px -14px rgba(148,116,196,0.38)";
      }}
      onMouseLeave={(e) => {
        e.currentTarget.style.transform = "translateY(0)";
        e.currentTarget.style.boxShadow = "0 10px 28px -14px rgba(148,116,196,0.28)";
      }}
    >
      <div className="relative overflow-hidden" style={{ background: T.paper }}>
        <img
          src={resolveImageUrl(product.image)}
          alt={product.product_name}
          className="h-52 w-full object-contain p-6 transition-transform duration-500 ease-out group-hover:scale-110 sm:h-44"
        />
        <span
          className="absolute left-3 top-3 rounded-full px-2.5 py-1 text-[11px] font-bold uppercase tracking-wider"
          style={{ background: "rgba(255,255,255,0.9)", color: T.inkStrong }}
        >
          {product.brand}
        </span>
        <FavoriteHeart active={isFavorite} onToggle={() => onToggleFavorite(product.product_id)} />
      </div>
      <div className="flex flex-1 flex-col gap-1 px-4 py-4">
        <span className="font-mono text-[11px] tracking-widest" style={{ color: T.inkSoft }}>
          {product.model_number}
        </span>
        <span className="text-sm font-semibold leading-snug" style={{ color: T.inkStrong }}>
          {product.product_name}
        </span>
        <div className="mt-2 flex items-baseline gap-1">
          <span className="text-xs font-medium" style={{ color: T.inkSoft }}>
            ราคาเริ่มต้น
          </span>
          {minPrice(product.listings) !== null ? (
            <span style={{ fontFamily: "'Fraunces', serif", color: T.pinkText }} className="text-xl font-bold">
              ฿{fmtBaht(minPrice(product.listings) ?? 0)}
            </span>
          ) : (
            <span style={{ fontFamily: "'Fraunces', serif", color: T.inkSoft }} className="text-xl font-bold">
              หมดสต๊อก
            </span>
          )}
        </div>
      </div>
    </div>
  );
}

function ListingRow({ listing, isBest }: { listing: Listing; isBest: boolean }) {
  const platform = PLATFORM_STYLE[listing.platform] || { bg: "#eee", fg: "#333" };
  const hasPrice = listing.net_price !== null && listing.net_price !== undefined;
  const isOutOfStock = listing.in_stock === false || !hasPrice;
  const changeUp = !isOutOfStock && (listing.price_change ?? 0) > 0;
  const changeDown = !isOutOfStock && (listing.price_change ?? 0) < 0;

  return (
    <div
      className="relative flex flex-col gap-3 rounded-2xl p-4 transition-all duration-200 sm:flex-row sm:items-center sm:justify-between"
      style={{
        background: isBest ? T.peach : isOutOfStock ? "#F1F2F5" : T.bgVia,
        border: isBest ? `2px solid #F3C97C` : `1px solid ${isOutOfStock ? "#DDE1E7" : T.blueLine}`,
        opacity: isOutOfStock ? 0.55 : 1,
      }}
    >
      {isBest && (
        <div
          className="absolute -top-3 left-4 flex items-center gap-1 rounded-full px-2.5 py-0.5 text-[11px] font-bold"
          style={{ background: "#F3C97C", color: T.peachText }}
        >
          <Tag size={11} strokeWidth={2.5} />
          Best Value คุ้มค่าที่สุด
        </div>
      )}
      {isOutOfStock && (
        <div
          className="absolute -top-3 right-4 rounded-full px-2.5 py-0.5 text-[11px] font-bold"
          style={{ background: "#FBDADA", color: "#B4453B" }}
        >
          หมดสต๊อก
        </div>
      )}

      <div className="flex items-center gap-3">
        <span
          className="rounded-full px-2.5 py-1 text-[11px] font-bold uppercase tracking-wide"
          style={{ background: platform.bg, color: platform.fg }}
        >
          {listing.platform}
        </span>
        <div className="flex flex-col">
          <span className="text-sm font-semibold" style={{ color: isOutOfStock ? T.inkSoft : T.inkStrong }}>
            {listing.shop_name}
          </span>
          {!isOutOfStock && (
            <div className="flex items-center gap-1 text-xs font-semibold">
              {changeDown && (
                <span className="flex items-center gap-0.5" style={{ color: T.green }}>
                  <ArrowDown size={12} strokeWidth={3} />
                  ลดลง ฿{fmtBaht(Math.abs(listing.price_change ?? 0))}
                </span>
              )}
              {changeUp && (
                <span className="flex items-center gap-0.5" style={{ color: T.red }}>
                  <ArrowUp size={12} strokeWidth={3} />
                  เพิ่มขึ้น ฿{fmtBaht(listing.price_change ?? 0)}
                </span>
              )}
              {!changeUp && !changeDown && (
                <span className="flex items-center gap-0.5" style={{ color: T.inkSoft }}>
                  <Minus size={12} strokeWidth={3} />
                  ราคาคงที่
                </span>
              )}
            </div>
          )}
          {isOutOfStock && (
            <span className="text-xs font-medium" style={{ color: T.inkSoft }}>
              ไม่สามารถสั่งซื้อได้ในขณะนี้
            </span>
          )}
          {(listing.coupon !== undefined || listing.shipping !== undefined) && (
            <div className="mt-0.5 flex items-center gap-1.5 text-[11px] font-medium" style={{ color: T.inkSoft }}>
              {listing.coupon !== undefined && listing.coupon > 0 && <span>คูปองลด ฿{fmtBaht(listing.coupon)}</span>}
              {listing.coupon > 0 && listing.shipping !== undefined && <span>·</span>}
              {listing.shipping !== undefined && (
                <span>{listing.shipping === 0 ? "ส่งฟรี" : `ค่าส่ง ฿${fmtBaht(listing.shipping ?? 0)}`}</span>
              )}
            </div>
          )}
        </div>
      </div>

      <div className="flex items-center justify-between gap-4 sm:justify-end">
        {isOutOfStock ? (
          hasPrice ? (
            <span className="text-base font-bold line-through md:text-lg" style={{ color: T.inkSoft }}>
              ฿{fmtBaht(listing.net_price ?? 0)}
            </span>
          ) : (
            <span className="text-base font-bold md:text-lg" style={{ color: T.inkSoft }}>
              N/A
            </span>
          )
        ) : (
          <span style={{ fontFamily: "'Fraunces', serif", color: T.inkStrong }} className="text-xl font-bold md:text-2xl">
            ฿{fmtBaht(listing.net_price ?? 0)}
          </span>
        )}
        {isOutOfStock ? (
          <button
            disabled
            className="flex cursor-not-allowed items-center gap-1.5 rounded-full px-4 py-2.5 text-sm font-bold pointer-events-none sm:px-3.5 sm:py-2 sm:text-xs"
            style={{ background: "#E2E5EA", color: "#9AA3B2" }}
          >
            สินค้าหมด
          </button>
        ) : (
          <a
            href={listing.url}
            target="_blank"
            rel="noopener noreferrer"
            className="group flex items-center gap-1.5 rounded-full px-4 py-2.5 text-sm font-bold transition-colors duration-200 sm:px-3.5 sm:py-2 sm:text-xs"
            style={{ background: T.blue, color: T.inkStrong }}
            onMouseEnter={(e) => (e.currentTarget.style.background = T.blueHover)}
            onMouseLeave={(e) => (e.currentTarget.style.background = T.blue)}
          >
            ไปที่ร้านค้า
            <ExternalLink size={13} className="transition-transform duration-200 group-hover:translate-x-0.5 group-hover:-translate-y-0.5" />
          </a>
        )}
      </div>
    </div>
  );
}

function ProductModal({
  product,
  visible,
  onClose,
  isFavorite,
  onToggleFavorite,
  onSelectRelated,
}: {
  product: Product | null;
  visible: boolean;
  onClose: () => void;
  isFavorite: boolean;
  onToggleFavorite: (productId: string) => void;
  onSelectRelated: (product: Product) => void;
}) {
  // iOS/iPadOS Safari คำนวณหน่วย vh ผิดพลาดเมื่ออยู่ใน iframe (เช่น Claude Artifacts) โดยเฉพาะตอนหมุนจอ
  // จึงวัดความสูงจอจริงด้วย JS แทนพึ่งพา CSS vh อย่างเดียว แล้วอัปเดตทุกครั้งที่ resize/orientation เปลี่ยน
  const [viewportHeight, setViewportHeight] = useState(() =>
    typeof window !== "undefined" ? window.visualViewport?.height || window.innerHeight : 800
  );

  useEffect(() => {
    const updateHeight = () => {
      setViewportHeight(window.visualViewport?.height || window.innerHeight);
    };
    updateHeight();
    window.addEventListener("resize", updateHeight);
    window.addEventListener("orientationchange", updateHeight);
    window.visualViewport?.addEventListener("resize", updateHeight);
    return () => {
      window.removeEventListener("resize", updateHeight);
      window.removeEventListener("orientationchange", updateHeight);
      window.visualViewport?.removeEventListener("resize", updateHeight);
    };
  }, []);

  const modalMaxHeightPx = Math.round(viewportHeight * 0.9);

  const sortedListings = useMemo<Listing[]>(() => {
    if (!product) return [];
    return [...product.listings].sort((a, b) => {
      const aOut = a.in_stock === false || a.net_price === null || a.net_price === undefined;
      const bOut = b.in_stock === false || b.net_price === null || b.net_price === undefined;
      // ร้านที่ "หมดสต๊อก" ให้จมลงล่างสุดเสมอ ไม่ว่าจะมีราคาส่งมาด้วยหรือไม่
      if (aOut && !bOut) return 1;
      if (!aOut && bOut) return -1;
      if (aOut && bOut) return 0;
      // ร้านที่มีของ (in stock) เรียงราคาถูกไปแพงตามปกติ
      return (a.net_price ?? 0) - (b.net_price ?? 0);
    });
  }, [product]);

  const relatedProducts = useMemo<Product[]>(() => {
    if (!product) return [];
    return getRelatedProducts(product.product_id);
  }, [product]);

  if (!product) return null;

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4 transition-opacity duration-300"
      style={{ background: "rgba(51,65,85,0.45)", backdropFilter: "blur(2px)", opacity: visible ? 1 : 0 }}
      onClick={onClose}
    >
      <div
        role="dialog"
        aria-modal="true"
        onClick={(e) => e.stopPropagation()}
        className="flex max-h-[90vh] max-h-[90dvh] w-[95%] flex-col overflow-hidden rounded-3xl transition-all duration-300 ease-out sm:w-full sm:max-w-3xl"
        style={{
          background: T.paper,
          maxHeight: modalMaxHeightPx,
          transform: visible ? "scale(1)" : "scale(0.96)",
          opacity: visible ? 1 : 0,
          boxShadow: "0 30px 60px -20px rgba(148,116,196,0.4)",
        }}
      >
        <div
          className="flex flex-shrink-0 items-center justify-between gap-2 px-3 py-2.5 sm:px-5 sm:py-3"
          style={{ borderBottom: `1px solid ${T.blueLine}` }}
        >
          <button
            onClick={onClose}
            className="group flex flex-shrink-0 items-center gap-1.5 rounded-full px-3 py-2 text-sm font-bold transition-colors duration-150 sm:px-2.5 sm:py-1.5"
            style={{ color: T.pinkText }}
            onMouseEnter={(e) => (e.currentTarget.style.background = T.pink)}
            onMouseLeave={(e) => (e.currentTarget.style.background = "transparent")}
          >
            <ArrowLeft size={16} strokeWidth={2.5} className="transition-transform duration-150 group-hover:-translate-x-0.5" />
            <span className="hidden sm:inline">กลับหน้าแรก</span>
          </button>

          <span className="min-w-0 flex-1 truncate text-center text-sm font-semibold sm:hidden" style={{ color: T.inkStrong }}>
            {product.product_name}
          </span>

          <button
            onClick={onClose}
            aria-label="ปิดหน้าต่าง"
            className="flex h-10 w-10 flex-shrink-0 items-center justify-center rounded-full transition-transform duration-150 hover:scale-110 sm:h-9 sm:w-9"
            // NOTE: T.blueSoft does not exist on the T design-token object (pre-existing bug, left
            // as-is per this pass's scope - see report). Cast so this compiles as `undefined` like before.
            style={{ background: (T as Record<string, string>).blueSoft }}
          >
            <X size={18} color={T.inkStrong} strokeWidth={2.5} />
          </button>
        </div>

        <div className="relative flex-shrink-0" style={{ background: T.bgTo }}>
          <img
            src={resolveImageUrl(product.image)}
            alt={product.product_name}
            className="h-56 w-full object-contain p-6 sm:h-64"
          />
          <span
            className="absolute left-4 top-4 rounded-full px-2.5 py-1 text-[11px] font-bold uppercase tracking-wider"
            style={{ background: "rgba(255,255,255,0.9)", color: T.inkStrong }}
          >
            {product.brand}
          </span>
          <div className="absolute bottom-3 right-3">
            <FavoriteHeart active={isFavorite} onToggle={() => onToggleFavorite(product.product_id)} floating={false} />
          </div>
        </div>

        <div className="min-h-0 flex-1 overflow-y-auto px-5 py-5 sm:px-7" style={{ WebkitOverflowScrolling: "touch", overscrollBehavior: "contain" }}>
          <span className="font-mono text-xs tracking-widest" style={{ color: T.inkSoft }}>
            {product.model_number}
          </span>
          <h2 style={{ fontFamily: "'Fraunces', serif", color: T.inkStrong }} className="mt-1 text-2xl font-bold leading-tight">
            {product.product_name}
          </h2>
          <p className="mt-2 text-sm leading-relaxed" style={{ color: T.inkSoft }}>
            {product.specs}
          </p>

          <div className="my-5 border-t-2 border-dashed" style={{ borderColor: T.blueLine }} />

          <h3 className="mb-3 text-sm font-bold" style={{ color: T.inkStrong }}>
            เปรียบเทียบราคาจาก {product.listings.length} แพลตฟอร์ม
          </h3>
          <div className="flex flex-col gap-4 pt-3">
            {sortedListings.map((listing, idx) => (
              <ListingRow
                key={listing.shop_name + listing.platform}
                listing={listing}
                isBest={idx === 0 && listing.net_price !== null && listing.net_price !== undefined}
              />
            ))}
          </div>

          <div className="my-5 border-t-2 border-dashed" style={{ borderColor: T.blueLine }} />

          <h3 className="mb-3 flex items-center gap-1.5 text-sm font-bold" style={{ color: T.inkStrong }}>
            <TrendingUp size={15} />
            กราฟราคาย้อนหลัง
          </h3>
          <PriceHistoryChart productId={product.product_id} />

          <h3 className="mb-3 mt-5 text-sm font-bold" style={{ color: T.inkStrong }}>
            ตารางเปรียบเทียบราคาละเอียด (รวมคูปอง/ค่าส่ง)
          </h3>
          <CompareTable productId={product.product_id} />

          {relatedProducts.length > 0 && (
            <>
              <div className="my-5 border-t-2 border-dashed" style={{ borderColor: T.blueLine }} />
              <h3 className="mb-3 text-sm font-bold" style={{ color: T.inkStrong }}>
                สินค้าที่มักซื้อคู่กัน
              </h3>
              <div className="-mx-1 flex gap-3 overflow-x-auto px-1 pb-1">
                {relatedProducts.map((rp) => (
                  <button
                    key={rp.product_id}
                    onClick={() => onSelectRelated(rp)}
                    className="flex w-28 flex-shrink-0 flex-col overflow-hidden rounded-2xl text-left transition-transform duration-150 hover:-translate-y-0.5"
                    style={{ background: T.bgVia, border: `1px solid ${T.blueLine}` }}
                  >
                    <div className="h-20 w-full" style={{ background: T.paper }}>
                      <img src={resolveImageUrl(rp.image)} alt={rp.product_name} className="h-full w-full object-contain p-2" />
                    </div>
                    <div className="flex flex-col gap-0.5 px-2 py-2">
                      <span className="truncate text-[11px] font-semibold leading-tight" style={{ color: T.inkStrong }}>
                        {rp.product_name}
                      </span>
                      <span style={{ fontFamily: "'Fraunces', serif", color: T.pinkText }} className="text-xs font-bold">
                        {/* NOTE: unlike the ProductCard use of minPrice() elsewhere, this one has no
                        null-guard - if minPrice() is null (all listings out of stock) fmtBaht(null) would
                        throw at runtime. Pre-existing gap, left as-is per this pass's scope - see report. */}
                        ฿{fmtBaht(minPrice(rp.listings) ?? 0)}
                      </span>
                    </div>
                  </button>
                ))}
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

// ============================================================================
// FEATURE: หน้า Admin (เพิ่ม/แก้ไข/ลบ products, listings, coupons ผ่าน API จริง)
// ============================================================================
// หมายเหตุสำคัญ: ผมไม่มีไฟล์ schema/main.py จริงของคุณอยู่ในมือ โครงสร้างฟิลด์ด้านล่างนี้
// เป็นการ "อนุมาน" จากโครงสร้างข้อมูลที่ frontend ใช้อยู่แล้ว (ดู PRODUCTS array ด้านบน)
// กรุณาปรับชื่อคอลัมน์ให้ตรงกับ schema จริงของคุณถ้าไม่ตรงกัน (ดูคำอธิบายเพิ่มเติมในไฟล์ admin_routes.py ที่แนบมาด้วย)

// Generic row shape for the admin CRUD tables/forms below - fields vary per entity
// (see ADMIN_ENTITIES), so this stays loosely typed by design rather than one interface per table.
type AdminRow = Record<string, any>;

interface AdminEntityField {
  name: string;
  label: string;
  type: "text" | "number" | "textarea" | "checkbox";
  required?: boolean;
  readOnlyOnEdit?: boolean;
  placeholder?: string;
}

interface AdminEntityConfig {
  label: string;
  endpoint: string;
  idField: string;
  fields: AdminEntityField[];
}

// บัญชีเดียวใช้ทุกที่ (ลูกค้าทั่วไป/แอดมิน แยกกันด้วย role ไม่ใช่ระบบ login คนละชุด) - เก็บ session ใน
// localStorage เสมอ ทั้งฝั่ง UserApp (ปุ่มเข้าสู่ระบบใน navbar) และฝั่ง /admin (ดู App() ด้านล่าง)
const USER_TOKEN_STORAGE_KEY = "koomsure_user_token";
const USER_EMAIL_STORAGE_KEY = "koomsure_user_email";
const USER_ROLE_STORAGE_KEY = "koomsure_user_role";

// STEP 1: Generic fetch helper สำหรับเรียก POST / PUT / DELETE ไปที่ FastAPI backend
// authToken ตั้งค่าจาก localStorage ตั้งแต่โหลดไฟล์เลย (ไม่ต้องรอ React state) แล้วแนบเป็น Bearer token
// ให้ทุก request อัตโนมัติ - ใช้โดย apiRequest (admin CRUD) เท่านั้น ฝั่ง favorites ใช้ fetch ตรงๆ แยกต่างหาก
let authToken: string | null = localStorage.getItem(USER_TOKEN_STORAGE_KEY);

async function apiRequest(method: string, url: string, body?: unknown): Promise<any> {
  const headers: Record<string, string> = { "Content-Type": "application/json" };
  if (authToken) headers["Authorization"] = `Bearer ${authToken}`;
  const res = await fetch(url, {
    method,
    headers,
    body: body !== undefined ? JSON.stringify(body) : undefined,
  });
  if (!res.ok) {
    let message = `${method} ${url} ล้มเหลว (HTTP ${res.status})`;
    try {
      const errJson = await res.json();
      if (errJson && errJson.detail) {
        message = typeof errJson.detail === "string" ? errJson.detail : JSON.stringify(errJson.detail);
      }
    } catch (e) {
      /* response ไม่ใช่ JSON ก็ใช้ข้อความ default ไป */
    }
    throw new Error(message);
  }
  if (res.status === 204) return null;
  return res.json();
}

// STEP 2: นิยามฟิลด์ของแต่ละตาราง ใช้ขับเคลื่อนทั้งตาราง list และฟอร์ม Add/Edit แบบ generic
// (ไม่ต้องเขียนฟอร์มแยกทีละตาราง) - endpoint ต้องตรงกับที่เพิ่มใน backend (ดู admin_routes.py)
const ADMIN_ENTITIES: Record<string, AdminEntityConfig> = {
  products: {
    label: "สินค้า (Products)",
    endpoint: `${API_BASE}/api/admin/products`,
    idField: "product_id",
    fields: [
      { name: "product_id", label: "Product ID", type: "text", required: true, readOnlyOnEdit: true, placeholder: "เช่น P029" },
      { name: "brand", label: "แบรนด์", type: "text", required: true },
      { name: "model_number", label: "รุ่น (Model Number)", type: "text", required: true },
      { name: "product_name", label: "ชื่อสินค้า", type: "text", required: true },
      { name: "image", label: "URL รูปภาพ", type: "text" },
      { name: "specs", label: "สเปกโดยย่อ", type: "textarea" },
    ],
  },
  listings: {
    label: "ร้านค้า/ราคา (Listings)",
    endpoint: `${API_BASE}/api/admin/listings`,
    idField: "id",
    fields: [
      { name: "product_id", label: "Product ID", type: "text", required: true, placeholder: "เช่น P001" },
      { name: "platform", label: "แพลตฟอร์ม", type: "text", required: true },
      { name: "shop_name", label: "ชื่อร้าน", type: "text", required: true },
      { name: "net_price", label: "ราคาสุทธิ (บาท)", type: "number", required: true },
      { name: "price_change", label: "ส่วนต่างราคา (ปัจจุบัน - เดิม)", type: "number" },
      { name: "shipping", label: "ค่าส่ง (บาท)", type: "number" },
      { name: "in_stock", label: "มีสินค้า (In Stock)", type: "checkbox" },
      { name: "url", label: "ลิงก์สินค้า", type: "text" },
    ],
  },
  coupons: {
    label: "คูปอง (Coupons)",
    endpoint: `${API_BASE}/api/admin/coupons`,
    idField: "id",
    fields: [
      { name: "listing_id", label: "Listing ID", type: "number", required: true, placeholder: "id ของ listing ที่คูปองนี้ผูกอยู่" },
      { name: "code", label: "โค้ดคูปอง", type: "text" },
      { name: "amount", label: "ส่วนลด (บาท)", type: "number", required: true },
      { name: "description", label: "คำอธิบาย", type: "text" },
    ],
  },
};

// STEP 4: ฟอร์ม Add/Edit แบบ generic ขับเคลื่อนด้วย field config ของแต่ละ entity
function AdminEntityForm({
  config,
  initialValues,
  onSave,
  onCancel,
}: {
  config: AdminEntityConfig;
  initialValues: AdminRow | null;
  onSave: (values: AdminRow) => Promise<void>;
  onCancel: () => void;
}) {
  const [values, setValues] = useState<AdminRow>(() => {
    const base: AdminRow = {};
    config.fields.forEach((f) => {
      base[f.name] = initialValues ? initialValues[f.name] ?? "" : f.type === "checkbox" ? true : "";
    });
    return base;
  });
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");

  const handleChange = (field: AdminEntityField, raw: any) => {
    let val = raw;
    if (field.type === "number") val = raw === "" ? "" : Number(raw);
    setValues((prev) => ({ ...prev, [field.name]: val }));
  };

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    const missing = config.fields.find((f) => f.required && (values[f.name] === "" || values[f.name] === undefined || values[f.name] === null));
    if (missing) {
      setError(`กรุณากรอก "${missing.label}"`);
      return;
    }
    setSaving(true);
    setError("");
    try {
      await onSave(values);
    } catch (err) {
      setError((err as Error).message || "บันทึกไม่สำเร็จ");
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4" style={{ background: "rgba(51,65,85,0.45)" }} onClick={onCancel}>
      <form
        onSubmit={handleSubmit}
        onClick={(e) => e.stopPropagation()}
        className="max-h-[85vh] w-full max-w-md overflow-y-auto rounded-3xl p-6"
        style={{ background: T.paper, boxShadow: "0 30px 60px -20px rgba(148,116,196,0.4)" }}
      >
        <h3 className="mb-4 text-base font-bold" style={{ color: T.inkStrong }}>
          {initialValues ? "แก้ไขรายการ" : "เพิ่มรายการใหม่"} — {config.label}
        </h3>

        <div className="flex flex-col gap-3">
          {config.fields.map((f) => {
            const isReadOnly = f.readOnlyOnEdit && !!initialValues;
            if (f.type === "checkbox") {
              return (
                <label key={f.name} className="flex items-center gap-2 text-sm font-semibold" style={{ color: T.inkStrong }}>
                  <input
                    type="checkbox"
                    checked={!!values[f.name]}
                    onChange={(e) => handleChange(f, e.target.checked)}
                    className="h-4 w-4"
                  />
                  {f.label}
                </label>
              );
            }
            if (f.type === "textarea") {
              return (
                <div key={f.name}>
                  <label className="mb-1 block text-xs font-bold" style={{ color: T.inkStrong }}>
                    {f.label} {f.required && <span style={{ color: T.red }}>*</span>}
                  </label>
                  <textarea
                    value={values[f.name] ?? ""}
                    onChange={(e) => handleChange(f, e.target.value)}
                    rows={3}
                    className="w-full rounded-xl px-3 py-2 text-sm outline-none"
                    style={{ background: T.bgVia, border: `1px solid ${T.blueLine}`, color: T.inkStrong }}
                  />
                </div>
              );
            }
            return (
              <div key={f.name}>
                <label className="mb-1 block text-xs font-bold" style={{ color: T.inkStrong }}>
                  {f.label} {f.required && <span style={{ color: T.red }}>*</span>}
                </label>
                <input
                  type={f.type === "number" ? "number" : "text"}
                  value={values[f.name] ?? ""}
                  onChange={(e) => handleChange(f, e.target.value)}
                  placeholder={f.placeholder}
                  disabled={isReadOnly}
                  className="w-full rounded-xl px-3 py-2 text-sm outline-none disabled:opacity-50"
                  style={{ background: T.bgVia, border: `1px solid ${T.blueLine}`, color: T.inkStrong }}
                />
              </div>
            );
          })}
        </div>

        {error && (
          <p className="mt-3 flex items-center gap-1 text-xs font-semibold" style={{ color: T.red }}>
            <AlertCircle size={13} />
            {error}
          </p>
        )}

        <div className="mt-5 flex gap-2">
          <button
            type="button"
            onClick={onCancel}
            className="flex-1 rounded-full px-4 py-2.5 text-sm font-bold"
            style={{ background: T.bgVia, color: T.inkStrong }}
          >
            ยกเลิก
          </button>
          <button
            type="submit"
            disabled={saving}
            className="flex-1 rounded-full px-4 py-2.5 text-sm font-bold text-white disabled:opacity-60"
            style={{ background: T.pinkHeart }}
          >
            {saving ? "กำลังบันทึก..." : "บันทึก"}
          </button>
        </div>
      </form>
    </div>
  );
}

// STEP 5: ตาราง list + ปุ่ม เพิ่ม/แก้ไข/ลบ ของ 1 entity - ใช้ config เดียวกับฟอร์มด้านบน
interface AdminTableState {
  status: "loading" | "success" | "error";
  rows: AdminRow[];
}

function AdminEntityTable({ entityKey }: { entityKey: string }) {
  const config = ADMIN_ENTITIES[entityKey];
  const [state, setState] = useState<AdminTableState>({ status: "loading", rows: [] });
  const [formOpen, setFormOpen] = useState(false);
  const [editingRow, setEditingRow] = useState<AdminRow | null>(null);
  const [deletingRow, setDeletingRow] = useState<AdminRow | null>(null);
  const [actionError, setActionError] = useState("");

  const loadRows = useCallback(() => {
    setState({ status: "loading", rows: [] });
    apiRequest("GET", config.endpoint)
      .then((rows) => setState({ status: "success", rows: Array.isArray(rows) ? rows : [] }))
      .catch(() => setState({ status: "error", rows: [] }));
  }, [config.endpoint]);

  useEffect(() => {
    loadRows();
  }, [loadRows]);

  const handleSave = async (values: AdminRow) => {
    if (editingRow) {
      await apiRequest("PUT", `${config.endpoint}/${editingRow[config.idField]}`, values);
    } else {
      await apiRequest("POST", config.endpoint, values);
    }
    setFormOpen(false);
    setEditingRow(null);
    loadRows();
  };

  const handleDelete = async () => {
    setActionError("");
    try {
      await apiRequest("DELETE", `${config.endpoint}/${deletingRow![config.idField]}`);
      setDeletingRow(null);
      loadRows();
    } catch (err) {
      setActionError((err as Error).message || "ลบไม่สำเร็จ");
    }
  };

  const columns = config.fields.map((f) => f.name);

  return (
    <div>
      <div className="mb-3 flex items-center justify-between">
        <span className="text-sm font-semibold" style={{ color: T.inkSoft }}>
          ทั้งหมด {state.rows.length} รายการ
        </span>
        <button
          onClick={() => {
            setEditingRow(null);
            setFormOpen(true);
          }}
          className="flex items-center gap-1.5 rounded-full px-3.5 py-2 text-xs font-bold text-white"
          style={{ background: T.pinkHeart }}
        >
          <Plus size={14} />
          เพิ่มรายการใหม่
        </button>
      </div>

      {state.status === "loading" && (
        <div className="flex flex-col gap-2">
          {[0, 1, 2].map((i) => (
            <div key={i} className="h-11 animate-pulse rounded-xl" style={{ background: T.bgVia }} />
          ))}
        </div>
      )}

      {state.status === "error" && (
        <div className="rounded-2xl border border-dashed py-10 text-center text-sm" style={{ borderColor: T.blueLine, color: T.inkSoft }}>
          โหลดข้อมูลไม่สำเร็จ ตรวจสอบว่า backend รันอยู่ที่ {API_BASE} และมี endpoint {config.endpoint} หรือยัง
        </div>
      )}

      {state.status === "success" && state.rows.length === 0 && (
        <div className="rounded-2xl border border-dashed py-10 text-center text-sm" style={{ borderColor: T.blueLine, color: T.inkSoft }}>
          ยังไม่มีข้อมูล ลองกด "เพิ่มรายการใหม่"
        </div>
      )}

      {state.status === "success" && state.rows.length > 0 && (
        <div className="overflow-x-auto rounded-2xl" style={{ border: `1px solid ${T.blueLine}` }}>
          <table className="w-full min-w-[640px] border-collapse text-left text-xs">
            <thead>
              <tr style={{ background: T.bgVia }}>
                {columns.map((c) => (
                  <th key={c} className="whitespace-nowrap px-3 py-2.5 font-bold" style={{ color: T.inkStrong }}>
                    {c}
                  </th>
                ))}
                <th className="px-3 py-2.5" />
              </tr>
            </thead>
            <tbody>
              {state.rows.map((row) => (
                <tr key={row[config.idField]} style={{ borderTop: `1px solid ${T.blueLine}` }}>
                  {columns.map((c) => (
                    <td key={c} className="whitespace-nowrap px-3 py-2.5" style={{ color: T.ink }}>
                      {String(row[c] ?? "-")}
                    </td>
                  ))}
                  <td className="whitespace-nowrap px-3 py-2.5">
                    <div className="flex gap-1.5">
                      <button
                        onClick={() => {
                          setEditingRow(row);
                          setFormOpen(true);
                        }}
                        className="flex h-7 w-7 items-center justify-center rounded-full"
                        style={{ background: T.blue }}
                        aria-label="แก้ไข"
                      >
                        <Pencil size={12} />
                      </button>
                      <button
                        onClick={() => setDeletingRow(row)}
                        className="flex h-7 w-7 items-center justify-center rounded-full"
                        style={{ background: "#FBDADA", color: "#B4453B" }}
                        aria-label="ลบ"
                      >
                        <Trash2 size={12} />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {formOpen && (
        <AdminEntityForm
          config={config}
          initialValues={editingRow}
          onSave={handleSave}
          onCancel={() => {
            setFormOpen(false);
            setEditingRow(null);
          }}
        />
      )}

      {deletingRow && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4" style={{ background: "rgba(51,65,85,0.45)" }}>
          <div className="w-full max-w-sm rounded-3xl p-6" style={{ background: T.paper }}>
            <p className="mb-1 text-sm font-bold" style={{ color: T.inkStrong }}>
              ยืนยันการลบรายการนี้?
            </p>
            <p className="mb-4 text-xs" style={{ color: T.inkSoft }}>
              {config.idField}: {String(deletingRow[config.idField])} — การลบไม่สามารถย้อนกลับได้
            </p>
            {actionError && (
              <p className="mb-3 text-xs font-semibold" style={{ color: T.red }}>
                {actionError}
              </p>
            )}
            <div className="flex gap-2">
              <button
                onClick={() => {
                  setDeletingRow(null);
                  setActionError("");
                }}
                className="flex-1 rounded-full px-4 py-2.5 text-sm font-bold"
                style={{ background: T.bgVia, color: T.inkStrong }}
              >
                ยกเลิก
              </button>
              <button onClick={handleDelete} className="flex-1 rounded-full px-4 py-2.5 text-sm font-bold text-white" style={{ background: T.red }}>
                ลบเลย
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// STEP 6: หน้า Dashboard หลักของแอดมิน - สลับ 3 แท็บ + ลิงก์ดูหน้าร้านจริง (เปิดแท็บใหม่) + ออกจากระบบ
