// STEP 7: โหลดแคตตาล็อกสินค้าสดจาก backend แล้ว "mutate" ลงในอาเรย์ PRODUCTS เดิม (ดูคอมเมนต์ตอนประกาศ PRODUCTS ด้านบน)
// เพื่อให้ทุกจุดในแอป (ProductCard, ตัวกรอง, Top Deal Dashboard ฯลฯ) เห็นข้อมูลใหม่โดยไม่ต้องแก้โค้ดเดิม
// ต้องมี endpoint นี้ที่ backend: GET /api/products คืนค่าเป็น array รูปแบบเดียวกับ PRODUCTS ที่ประกาศไว้ด้านบนเป๊ะๆ
// (product_id, brand, model_number, product_name, image, specs, listings: [...]) - ดู admin_routes.py ที่แนบมา
async function fetchLiveProducts(): Promise<Product[]> {
  const data = await apiRequest("GET", `${API_BASE}/api/products`);
  if (Array.isArray(data)) {
    PRODUCTS.splice(0, PRODUCTS.length, ...(data as Product[]));
  }
  return PRODUCTS;
}

// ============================================================================
// FEATURE: บัญชีผู้ใช้ (บัญชีเดียวกันทั้งลูกค้าทั่วไปและแอดมิน แยกกันด้วย role จาก DB เท่านั้น)
// จุดประสงค์หลักฝั่งลูกค้าทั่วไปคือให้ "รายการโปรด" ผูกกับบัญชีจริง อยู่ถาวรข้าม login/logout/เครื่องอื่น
// เก็บ token ไว้ใน localStorage เสมอ (ดู USER_TOKEN_STORAGE_KEY - ใช้ร่วมกันทั้ง UserApp และ App()'s /admin)
// ============================================================================
interface AuthResult {
  access_token: string;
  token_type: string;
  email: string;
  role: string;
}

async function extractErrorMessage(res: Response, fallback: string): Promise<string> {
  try {
    const errJson = await res.json();
    if (errJson && typeof errJson.detail === "string") return errJson.detail;
  } catch {
    /* response ไม่ใช่ JSON ก็ใช้ข้อความ default ไป */
  }
  return fallback;
}

async function registerUser(email: string, password: string): Promise<AuthResult> {
  const res = await fetch(`${API_BASE}/api/auth/register`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ email, password }),
  });
  if (!res.ok) throw new Error(await extractErrorMessage(res, "สมัครสมาชิกไม่สำเร็จ"));
  return res.json() as Promise<AuthResult>;
}

async function loginUser(email: string, password: string): Promise<AuthResult> {
  const res = await fetch(`${API_BASE}/api/auth/login`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ email, password }),
  });
  if (!res.ok) throw new Error(await extractErrorMessage(res, "เข้าสู่ระบบไม่สำเร็จ"));
  return res.json() as Promise<AuthResult>;
}

async function fetchFavorites(token: string): Promise<string[]> {
  const res = await fetch(`${API_BASE}/api/favorites`, { headers: { Authorization: `Bearer ${token}` } });
  if (!res.ok) throw new Error(await extractErrorMessage(res, "โหลดรายการโปรดไม่สำเร็จ"));
  return res.json() as Promise<string[]>;
}

async function addFavoriteRemote(token: string, productId: string): Promise<void> {
  const res = await fetch(`${API_BASE}/api/favorites/${productId}`, {
    method: "POST",
    headers: { Authorization: `Bearer ${token}` },
  });
  if (!res.ok) throw new Error(await extractErrorMessage(res, "บันทึกรายการโปรดไม่สำเร็จ"));
}

async function removeFavoriteRemote(token: string, productId: string): Promise<void> {
  const res = await fetch(`${API_BASE}/api/favorites/${productId}`, {
    method: "DELETE",
    headers: { Authorization: `Bearer ${token}` },
  });
  if (!res.ok) throw new Error(await extractErrorMessage(res, "ลบรายการโปรดไม่สำเร็จ"));
}

// ฟอร์ม login/สมัครสมาชิกแบบเดียว ใช้ร่วมกันทั้งลูกค้าทั่วไป (ปุ่มใน navbar) และแอดมิน (หน้า /admin) -
// บัญชีเดียวกันหมด สลับโหมดด้วยปุ่มลิงก์ด้านล่าง - เปิดเป็น modal ทับหน้าปัจจุบัน
function UserAuthForm({
  onSuccess,
  onCancel,
}: {
  onSuccess: (token: string, email: string, role: string) => void;
  onCancel: () => void;
}) {
  const [mode, setMode] = useState<"login" | "register">("login");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [submitting, setSubmitting] = useState(false);

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    setError("");
    setSubmitting(true);
    try {
      const data = mode === "login" ? await loginUser(email, password) : await registerUser(email, password);
      onSuccess(data.access_token, data.email, data.role);
    } catch (err) {
      setError((err as Error).message || "เกิดข้อผิดพลาด");
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div
      className="fixed inset-0 z-[70] flex items-center justify-center p-4"
      style={{ background: "rgba(51,65,85,0.45)" }}
      onClick={onCancel}
    >
      <form
        onSubmit={handleSubmit}
        onClick={(e) => e.stopPropagation()}
        className="w-full max-w-sm rounded-3xl p-7"
        style={{ background: T.paper, border: `1px solid ${T.blueLine}`, boxShadow: "0 30px 60px -20px rgba(148,116,196,0.4)" }}
      >
        <div className="mb-5 flex items-center gap-2">
          <div className="flex h-9 w-9 items-center justify-center rounded-2xl font-bold" style={{ background: T.pink, color: T.pinkText, fontFamily: "'Fraunces', serif" }}>
            K
          </div>
          <span style={{ fontFamily: "'Fraunces', serif", color: T.inkStrong }} className="text-lg font-bold">
            {mode === "login" ? "เข้าสู่ระบบ" : "สมัครสมาชิก"}
          </span>
        </div>

        <label className="mb-1 block text-xs font-bold" style={{ color: T.inkStrong }}>
          อีเมล
        </label>
        <input
          type="email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          className="mb-3 w-full rounded-xl px-3.5 py-2.5 text-sm outline-none"
          style={{ background: T.bgVia, border: `1px solid ${T.blueLine}`, color: T.inkStrong }}
          placeholder="you@example.com"
        />

        <label className="mb-1 block text-xs font-bold" style={{ color: T.inkStrong }}>
          รหัสผ่าน
        </label>
        <input
          type="password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          className="mb-2 w-full rounded-xl px-3.5 py-2.5 text-sm outline-none"
          style={{ background: T.bgVia, border: `1px solid ${T.blueLine}`, color: T.inkStrong }}
          placeholder="••••••••"
        />

        {error && (
          <p className="mb-2 flex items-center gap-1 text-xs font-semibold" style={{ color: T.red }}>
            <AlertCircle size={13} />
            {error}
          </p>
        )}

        <button
          type="submit"
          disabled={submitting}
          className="mt-2 flex w-full items-center justify-center gap-1.5 rounded-full px-4 py-2.5 text-sm font-bold text-white disabled:opacity-60"
          style={{ background: T.pinkHeart }}
        >
          <LogIn size={15} />
          {submitting ? "กำลังดำเนินการ..." : mode === "login" ? "เข้าสู่ระบบ" : "สมัครสมาชิก"}
        </button>

        <button
          type="button"
          onClick={() => {
            setMode(mode === "login" ? "register" : "login");
            setError("");
          }}
          className="mt-3 w-full text-center text-xs font-semibold underline"
          style={{ color: T.inkSoft }}
        >
          {mode === "login" ? "ยังไม่มีบัญชี? สมัครสมาชิก" : "มีบัญชีอยู่แล้ว? เข้าสู่ระบบ"}
        </button>

        <button type="button" onClick={onCancel} className="mt-2 w-full text-center text-xs font-semibold" style={{ color: T.inkSoft }}>
          ยกเลิก
        </button>
      </form>
    </div>
  );
}

function UserApp() {
  const [query, setQuery] = useState("");
  const [favorites, setFavorites] = useState<Set<string>>(() => new Set());
  const [showFavoritesOnly, setShowFavoritesOnly] = useState(false);
  const [activeCategory, setActiveCategory] = useState("all");
  const [activePriceRange, setActivePriceRange] = useState("all");
  const [budgetInput, setBudgetInput] = useState(""); // เก็บเป็น string เพื่อให้ควบคุมช่องว่าง/ค่าลบได้ตรงตามที่พิมพ์
  const [activeProduct, setActiveProduct] = useState<Product | null>(null);
  const [modalVisible, setModalVisible] = useState(false);

  // บัญชีผู้ใช้: session อยู่ถาวรใน localStorage (คีย์เดียวกับที่ App()'s /admin flow ใช้)
  const [userToken, setUserToken] = useState<string | null>(() => localStorage.getItem(USER_TOKEN_STORAGE_KEY));
  const [userEmail, setUserEmail] = useState<string | null>(() => localStorage.getItem(USER_EMAIL_STORAGE_KEY));
  const [userRole, setUserRole] = useState<string | null>(() => localStorage.getItem(USER_ROLE_STORAGE_KEY));
  const [showAuthForm, setShowAuthForm] = useState(false);

  // มี token ตั้งแต่ mount (restore จาก localStorage) หรือเพิ่ง login/สมัครสมาชิกสำเร็จ -> โหลดรายการโปรดจริงจาก backend
  useEffect(() => {
    if (!userToken) return;
    let cancelled = false;
    fetchFavorites(userToken)
      .then((ids) => {
        if (!cancelled) setFavorites(new Set(ids));
      })
      .catch(() => {
        // token หมดอายุ/ไม่ถูกต้อง - เคลียร์ session ทิ้งเงียบๆ ให้ผู้ใช้ login ใหม่เอง ไม่ทำให้แอป crash
        if (!cancelled) {
          authToken = null;
          setUserToken(null);
          setUserEmail(null);
          setUserRole(null);
          localStorage.removeItem(USER_TOKEN_STORAGE_KEY);
          localStorage.removeItem(USER_EMAIL_STORAGE_KEY);
          localStorage.removeItem(USER_ROLE_STORAGE_KEY);
        }
      });
    return () => {
      cancelled = true;
    };
  }, [userToken]);

  const handleAuthSuccess = useCallback((token: string, email: string, role: string) => {
    authToken = token;
    localStorage.setItem(USER_TOKEN_STORAGE_KEY, token);
    localStorage.setItem(USER_EMAIL_STORAGE_KEY, email);
    localStorage.setItem(USER_ROLE_STORAGE_KEY, role);
    setUserToken(token);
    setUserEmail(email);
    setUserRole(role);
    setShowAuthForm(false);
  }, []);

  const handleLogout = useCallback(() => {
    authToken = null;
    localStorage.removeItem(USER_TOKEN_STORAGE_KEY);
    localStorage.removeItem(USER_EMAIL_STORAGE_KEY);
    localStorage.removeItem(USER_ROLE_STORAGE_KEY);
    setUserToken(null);
    setUserRole(null);
    setUserEmail(null);
    setFavorites(new Set());
    setShowFavoritesOnly(false);
  }, []);

  // ป้องกันไม่ให้กรอกค่าติดลบ: อนุญาตให้ลบจนว่างได้ (ไม่กรอง) แต่ปฏิเสธค่าที่น้อยกว่า 0
  const handleBudgetChange = useCallback((e: ChangeEvent<HTMLInputElement>) => {
    const raw = e.target.value;
    if (raw === "") {
      setBudgetInput("");
      return;
    }
    const num = Number(raw);
    if (Number.isNaN(num) || num < 0) return; // เมินค่าติดลบ/ไม่ใช่ตัวเลขไปเลย ไม่อัปเดต state
    setBudgetInput(raw);
  }, []);

  const budgetValue = budgetInput.trim() === "" ? 0 : Number(budgetInput);

  // ต้อง login ก่อนถึงจะกดหัวใจได้ (ไม่งั้นเปิดฟอร์ม login/สมัครสมาชิกแทน) เพราะรายการโปรดผูกกับบัญชีจริงแล้ว
  // ไม่ใช่ local state ที่หายได้เหมือนเดิม - update แบบ optimistic แล้วย้อนกลับถ้า backend ล้มเหลว
  const toggleFavorite = useCallback(
    (productId: string) => {
      if (!userToken) {
        setShowAuthForm(true);
        return;
      }
      const wasFavorite = favorites.has(productId);
      setFavorites((prev) => {
        const next = new Set(prev);
        if (wasFavorite) next.delete(productId);
        else next.add(productId);
        return next;
      });
      const remoteCall = wasFavorite
        ? removeFavoriteRemote(userToken, productId)
        : addFavoriteRemote(userToken, productId);
      remoteCall.catch(() => {
        setFavorites((prev) => {
          const next = new Set(prev);
          if (wasFavorite) next.add(productId);
          else next.delete(productId);
          return next;
        });
      });
    },
    [userToken, favorites]
  );

  const results = useMemo(() => {
    const q = query.trim().toLowerCase();
    let list = PRODUCTS;
    if (q) {
      list = list.filter(
        (p) => p.model_number.toLowerCase().includes(q) || p.product_name.toLowerCase().includes(q)
      );
    }
    if (activeCategory !== "all") {
      list = list.filter((p) => categorize(p) === activeCategory);
    }
    if (activePriceRange !== "all") {
      const range = PRICE_RANGES.find((r) => r.id === activePriceRange);
      list = list.filter((p) => {
        const price = bestValuePrice(p.listings);
        return price !== null && range!.test(price);
      });
    }
    // ตัวกรองงบประมาณ: เทียบกับ "ราคาสุทธิที่ถูกที่สุด" ของสินค้า (ร้านที่มีของก่อนเสมอ เหมือนตรรกะ Best Value)
    // ถ้างบประมาณว่างหรือเป็น 0 ให้ข้ามการกรองนี้ไปเลย (แสดงสินค้าทั้งหมดตามปกติ)
    if (budgetValue > 0) {
      list = list.filter((p) => {
        const price = bestValuePrice(p.listings);
        return price !== null && price <= budgetValue;
      });
    }
    if (showFavoritesOnly) {
      list = list.filter((p) => favorites.has(p.product_id));
    }
    return list;
  }, [query, activeCategory, activePriceRange, budgetValue, showFavoritesOnly, favorites]);

  // เช็คว่ามีตัวกรอง/ค้นหา/งบประมาณตัวไหน active อยู่บ้าง เพื่อโชว์ปุ่ม "ล้างตัวกรอง" เฉพาะตอนจำเป็น (ไม่รก UI ตอนไม่มีอะไรให้ล้าง)
  // นอกจาก 3 ช่องที่โจทย์ระบุ (ค้นหา/งบประมาณ/หมวดหมู่) ยังรวมช่วงราคาและรายการโปรดด้วย เพื่อให้ผลลัพธ์
  // ตรงตามที่โจทย์ต้องการจริงๆ คือ "การ์ดสินค้าทุกชิ้นต้องกลับมาแสดงผลครบถ้วนเหมือนตอนโหลดเข้าเว็บครั้งแรก"
  const hasActiveFilters =
    query.trim() !== "" || budgetValue > 0 || activeCategory !== "all" || activePriceRange !== "all" || showFavoritesOnly;

  const clearFilters = useCallback(() => {
    setQuery("");
    setBudgetInput("");
    setActiveCategory("all");
    setActivePriceRange("all");
    setShowFavoritesOnly(false);
  }, []);

  const openModal = useCallback((product: Product) => {
    setActiveProduct(product);
    requestAnimationFrame(() => requestAnimationFrame(() => setModalVisible(true)));
    try {
      window.history.pushState({ koomsureModal: true }, "");
    } catch (e) {
      /* history API unavailable in this environment, ignore */
    }
  }, []);

  const closeModal = useCallback(() => {
    setModalVisible(false);
    setTimeout(() => setActiveProduct(null), 300);
  }, []);

  const handleSwitchProduct = useCallback(
    (nextProduct: Product) => {
      setModalVisible(false);
      setTimeout(() => {
        openModal(nextProduct);
      }, 300);
    },
    [openModal]
  );

  const handleClose = useCallback(() => {
    try {
      if (window.history.state && window.history.state.koomsureModal) {
        window.history.back();
        return;
      }
    } catch (e) {
      /* ignore */
    }
    closeModal();
  }, [closeModal]);

  useEffect(() => {
    if (!activeProduct) return;
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") handleClose();
    };
    const onPopState = () => closeModal();
    window.addEventListener("keydown", onKeyDown);
    window.addEventListener("popstate", onPopState);
    return () => {
      window.removeEventListener("keydown", onKeyDown);
      window.removeEventListener("popstate", onPopState);
    };
  }, [activeProduct, handleClose, closeModal]);

  return (
    <div
      className="min-h-screen w-full"
      style={{
        background: `linear-gradient(160deg, ${T.bgFrom} 0%, ${T.bgVia} 45%, ${T.bgTo} 100%)`,
        fontFamily: "'Inter', sans-serif",
      }}
    >
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Fraunces:wght@500;600;700&family=Inter:wght@400;500;600;700&family=IBM+Plex+Mono:wght@500&display=swap');
      `}</style>

      <header
        className="sticky top-0 z-10 w-full px-4 py-4 sm:px-6 sm:py-5"
        style={{ background: "rgba(255,255,255,0.7)", backdropFilter: "blur(10px)", borderBottom: `1px solid ${T.blueLine}` }}
      >
        <div className="mx-auto flex max-w-5xl flex-col gap-3 sm:gap-4">
          <div className="flex items-center justify-between gap-3">
            <div className="flex items-center gap-2">
              <div
                className="flex h-8 w-8 items-center justify-center rounded-2xl font-bold sm:h-9 sm:w-9"
                style={{ background: T.pink, color: T.pinkText, fontFamily: "'Fraunces', serif" }}
              >
                K
              </div>
              <span style={{ fontFamily: "'Fraunces', serif", color: T.inkStrong, letterSpacing: "0.02em" }} className="text-lg font-bold sm:text-xl">
                KoomSure
              </span>
            </div>

            <div className="flex items-center gap-3">
              <span className="hidden text-xs font-medium sm:inline" style={{ color: T.inkSoft }}>
                อัปเดตข้อมูลล่าสุด: วันนี้ 12:00 น.
              </span>
              <button
                onClick={() => setShowFavoritesOnly((v) => !v)}
                className="relative flex items-center gap-1.5 rounded-full px-3.5 py-2.5 text-sm font-bold transition-colors duration-150 sm:px-4 sm:py-2"
                style={{
                  background: showFavoritesOnly ? T.pinkHeart : T.paper,
                  color: showFavoritesOnly ? "#FFFFFF" : T.inkStrong,
                  border: `1px solid ${showFavoritesOnly ? T.pinkHeart : T.blueLine}`,
                }}
              >
                <Heart size={15} strokeWidth={2.4} fill={showFavoritesOnly ? "#FFFFFF" : "none"} />
                <span className="hidden sm:inline">ดูรายการโปรด</span>
                {favorites.size > 0 && (
                  <span
                    className="absolute -right-1.5 -top-1.5 flex h-5 min-w-[20px] items-center justify-center rounded-full px-1 text-[10px] font-bold"
                    style={{ background: T.pinkText, color: "#fff", border: "2px solid white" }}
                  >
                    {favorites.size}
                  </span>
                )}
              </button>

              {/* ปุ่มบัญชีลูกค้า - ตั้งใจให้เห็นชัดเจน (ต่างจากปุ่มแอดมินที่ซ่อนไว้ทั้งหมด) เพราะผู้ใช้ทั่วไป
                  ต้อง login เองเพื่อให้รายการโปรดผูกกับบัญชีและอยู่ถาวร ไม่มีเหตุผลต้องซ่อน */}
              {userEmail ? (
                <div className="flex items-center gap-1.5">
                  <span
                    className="hidden max-w-[140px] truncate text-xs font-semibold sm:inline"
                    style={{ color: T.inkSoft }}
                    title={userEmail}
                  >
                    {userEmail}
                  </span>
                  {/* เห็นเฉพาะบัญชีที่ role เป็น admin เท่านั้น (ลูกค้าทั่วไป login แล้วจะไม่เห็นปุ่มนี้เลย) -
                      กันไม่ต้องพิมพ์ /admin เองทุกครั้งหลัง login ไปแล้ว แต่ยังไม่มีปุ่มแบบนี้ให้คนทั่วไปเห็น */}
                  {userRole === "admin" && (
                    <button
                      onClick={() => {
                        window.location.href = "/admin";
                      }}
                      aria-label="ไปหน้าแอดมิน"
                      title="ไปหน้าแอดมิน"
                      className="flex h-10 w-10 items-center justify-center rounded-full transition-colors duration-150 sm:h-9 sm:w-9"
                      style={{ background: T.pinkHeart, color: "#FFFFFF" }}
                    >
                      <ShieldCheck size={15} strokeWidth={2.4} />
                    </button>
                  )}
                  <button
                    onClick={handleLogout}
                    aria-label="ออกจากระบบ"
                    title="ออกจากระบบ"
                    className="flex h-10 w-10 items-center justify-center rounded-full transition-colors duration-150 sm:h-9 sm:w-9"
                    style={{ background: T.paper, color: T.inkStrong, border: `1px solid ${T.blueLine}` }}
                  >
                    <LogOut size={15} strokeWidth={2.4} />
                  </button>
                </div>
              ) : (
                <button
                  onClick={() => setShowAuthForm(true)}
                  className="flex items-center gap-1.5 rounded-full px-3.5 py-2.5 text-sm font-bold transition-colors duration-150 sm:px-4 sm:py-2"
                  style={{ background: T.paper, color: T.inkStrong, border: `1px solid ${T.blueLine}` }}
                >
                  <User size={15} strokeWidth={2.4} />
                  <span className="hidden sm:inline">เข้าสู่ระบบ</span>
                </button>
              )}
            </div>
          </div>

          <div className="flex flex-col gap-3 sm:flex-row sm:items-center">
            <div className="relative w-full sm:max-w-md sm:flex-1">
              <Search size={18} className="pointer-events-none absolute left-3.5 top-1/2 -translate-y-1/2" style={{ color: T.inkSoft }} />
              <input
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                placeholder="ค้นหารุ่นสินค้า เช่น iPhone 16"
                className="w-full rounded-full py-3 pl-10 pr-4 text-sm outline-none transition-shadow duration-150 sm:py-2.5"
                style={{ background: T.paper, color: T.inkStrong, border: `1px solid ${T.blueLine}` }}
                onFocus={(e) => (e.currentTarget.style.boxShadow = `0 0 0 3px ${T.pink}`)}
                onBlur={(e) => (e.currentTarget.style.boxShadow = "none")}
              />
            </div>

            <div className="relative w-full sm:max-w-[230px]">
              <span
                className="pointer-events-none absolute left-3.5 top-1/2 -translate-y-1/2 text-sm font-bold"
                style={{ color: T.inkSoft }}
              >
                ฿
              </span>
              <input
                type="number"
                min="0"
                inputMode="numeric"
                value={budgetInput}
                onChange={handleBudgetChange}
                placeholder="ระบุงบประมาณสูงสุด (บาท)..."
                className="w-full rounded-full py-3 pl-8 pr-4 text-sm outline-none transition-shadow duration-150 sm:py-2.5"
                style={{ background: T.paper, color: T.inkStrong, border: `1px solid ${T.blueLine}` }}
                onFocus={(e) => (e.currentTarget.style.boxShadow = `0 0 0 3px ${T.pink}`)}
                onBlur={(e) => (e.currentTarget.style.boxShadow = "none")}
              />
            </div>
          </div>

          <div className="-mx-4 flex items-center gap-2 overflow-x-auto px-4 pb-1 sm:mx-0 sm:flex-wrap sm:overflow-visible sm:px-0 sm:pb-0">
            {CATEGORIES.map((cat) => {
              const active = activeCategory === cat.id;
              return (
                <button
                  key={cat.id}
                  onClick={() => setActiveCategory(cat.id)}
                  className="flex-shrink-0 whitespace-nowrap rounded-full px-3.5 py-2 text-sm font-bold transition-colors duration-150 sm:py-1.5 sm:text-xs"
                  style={{
                    background: active ? T.pinkHeart : T.paper,
                    color: active ? "#FFFFFF" : T.inkStrong,
                    border: `1px solid ${active ? T.pinkHeart : T.blueLine}`,
                  }}
                >
                  {cat.label}
                </button>
              );
            })}
            <span className="mx-0.5 hidden h-4 w-px flex-shrink-0 sm:inline-block" style={{ background: T.blueLine }} />
            <select
              value={activePriceRange}
              onChange={(e) => setActivePriceRange(e.target.value)}
              className="flex-shrink-0 rounded-full px-3.5 py-2 text-sm font-bold outline-none sm:py-1.5 sm:text-xs"
              style={{
                background: activePriceRange !== "all" ? T.pinkHeart : T.paper,
                color: activePriceRange !== "all" ? "#FFFFFF" : T.inkStrong,
                border: `1px solid ${activePriceRange !== "all" ? T.pinkHeart : T.blueLine}`,
              }}
            >
              {PRICE_RANGES.map((r) => (
                <option key={r.id} value={r.id}>
                  {r.label}
                </option>
              ))}
            </select>
            {hasActiveFilters && (
              <button
                onClick={clearFilters}
                className="flex flex-shrink-0 items-center gap-1.5 whitespace-nowrap rounded-full px-3.5 py-2 text-sm font-bold transition-colors duration-150 sm:py-1.5 sm:text-xs"
                style={{ background: "transparent", color: T.pinkText, border: `1.5px dashed ${T.pinkHeart}` }}
                onMouseEnter={(e) => (e.currentTarget.style.background = T.pink)}
                onMouseLeave={(e) => (e.currentTarget.style.background = "transparent")}
              >
                <RotateCcw size={13} strokeWidth={2.5} />
                ล้างตัวกรอง
              </button>
            )}
          </div>

          <span className="text-xs font-medium sm:hidden" style={{ color: T.inkSoft }}>
            อัปเดตข้อมูลล่าสุด: วันนี้ 12:00 น.
          </span>
        </div>
      </header>

      <main className="mx-auto max-w-5xl px-4 py-6 sm:px-6 sm:py-8">
        {!query.trim() && activeCategory === "all" && activePriceRange === "all" && budgetValue <= 0 && !showFavoritesOnly && (
          <TopDealDashboard onOpenProduct={openModal} />
        )}

        <div className="mb-6 flex items-baseline justify-between">
          <h1 className="text-lg font-bold" style={{ color: T.inkStrong }}>
            {showFavoritesOnly ? "รายการโปรดของฉัน" : "สินค้าทั้งหมด"}
          </h1>
          <span className="text-sm" style={{ color: T.inkSoft }}>
            พบ {results.length} รายการ
          </span>
        </div>

        {results.length === 0 ? (
          <div className="rounded-3xl border border-dashed py-16 text-center text-sm" style={{ borderColor: T.blueLine, color: T.inkSoft }}>
            {showFavoritesOnly ? "ยังไม่มีสินค้าที่บันทึกไว้ ลองกดรูปหัวใจที่การ์ดสินค้า" : "ไม่พบสินค้าที่ตรงกับเงื่อนไข 🐣 ลองปรับตัวกรองหรือคำค้นหาดูนะ"}
          </div>
        ) : (
          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 sm:gap-5 lg:grid-cols-3 lg:gap-6 xl:grid-cols-4">
            {results.map((product) => (
              <ProductCard
                key={product.product_id}
                product={product}
                onOpen={openModal}
                isFavorite={favorites.has(product.product_id)}
                onToggleFavorite={toggleFavorite}
              />
            ))}
          </div>
        )}
      </main>

      <ProductModal
        product={activeProduct}
        visible={modalVisible}
        onClose={handleClose}
        isFavorite={activeProduct ? favorites.has(activeProduct.product_id) : false}
        onToggleFavorite={toggleFavorite}
        onSelectRelated={handleSwitchProduct}
      />

      {showAuthForm && <UserAuthForm onSuccess={handleAuthSuccess} onCancel={() => setShowAuthForm(false)} />}
    </div>
  );
}

// ============================================================================
// STEP 8: App หลัก - จัดการสถานะ role (guest/admin) และสลับหน้า user / login / admin dashboard
// ============================================================================
// แอดมินไม่มีปุ่ม/ไอคอนเข้าสู่ระบบโผล่อยู่บนหน้าเว็บลูกค้าเลย (ผู้ใช้ทั่วไปไม่มีทางเจอ/สับสนว่ามันคืออะไร) -
// เข้าถึงได้ทางเดียวคือพิมพ์ path /admin ตรงๆ ใน browser ตรงตามที่เว็บ production ทั่วไปทำกัน (เช่น /wp-admin)
// เช็คแค่ตอน mount ครั้งแรกพอ เพราะไม่มีลิงก์ภายในแอปที่พาไปหน้านี้อยู่แล้ว (ไปได้ทางเดียวคือพิมพ์ path เอง ซึ่ง reload
// หน้าเว็บใหม่ทุกครั้งอยู่แล้ว) - ไม่ต้องเปลืองแรงทำ router/popstate listener เพิ่ม
function isAdminPath(): boolean {
  return window.location.pathname.startsWith("/admin");
}

export default function App() {
  // บัญชีเดียวใช้ทุกที่แล้ว (ดูคอมเมนต์ตอนประกาศ USER_TOKEN_STORAGE_KEY) - role มาจาก DB จริง ไม่ใช่คนละ
  // ระบบ login เหมือนก่อนหน้านี้ session เลย restore จาก localStorage ได้ตรงนี้เหมือน UserApp ทุกประการ
  const [authRole, setAuthRole] = useState<string | null>(() => localStorage.getItem(USER_ROLE_STORAGE_KEY));
  const [catalogKey, setCatalogKey] = useState(0); // bump ค่านี้เพื่อบังคับ UserApp mount ใหม่หลังข้อมูลสินค้าเปลี่ยน

  // โหลดแคตตาล็อกสินค้าจริงจาก backend ครั้งแรกตอนแอปเริ่มทำงาน (ก่อนหน้านี้ใช้ PRODUCTS แบบ hardcode ในไฟล์)
  useEffect(() => {
    fetchLiveProducts()
      .then(() => setCatalogKey((k) => k + 1))
      .catch(() => {
        /* โหลดไม่สำเร็จ - ปล่อยให้ใช้ PRODUCTS ชุด fallback ที่ฝังไว้ในไฟล์ต่อไป ไม่ทำให้แอป crash */
      });
  }, []);

  const handleLogout = () => {
    authToken = null;
    localStorage.removeItem(USER_TOKEN_STORAGE_KEY);
    localStorage.removeItem(USER_EMAIL_STORAGE_KEY);
    localStorage.removeItem(USER_ROLE_STORAGE_KEY);
    setAuthRole(null);
  };

  if (isAdminPath()) {
    if (!authRole) {
      return (
        <UserAuthForm
          onSuccess={(token, email, role) => {
            authToken = token;
            localStorage.setItem(USER_TOKEN_STORAGE_KEY, token);
            localStorage.setItem(USER_EMAIL_STORAGE_KEY, email);
            localStorage.setItem(USER_ROLE_STORAGE_KEY, role);
            setAuthRole(role);
          }}
          onCancel={() => {
            // ออกจาก /admin ไปหน้าเว็บลูกค้าจริงๆ (เปลี่ยน URL ด้วย ไม่ใช่แค่สลับ state) ให้ address bar ตรงกับที่เห็น
            window.location.href = "/";
          }}
        />
      );
    }

    if (authRole !== "admin") {
      // login สำเร็จแล้ว แต่บัญชีนี้ไม่ใช่แอดมิน (เช่น ลูกค้าทั่วไปหลงเข้ามาที่ /admin) - บอกตรงๆ ไม่ใช่ปล่อยผ่าน
      return (
        <div
          className="flex min-h-screen flex-col items-center justify-center gap-4 p-4 text-center"
          style={{ background: `linear-gradient(160deg, ${T.bgFrom} 0%, ${T.bgVia} 45%, ${T.bgTo} 100%)` }}
        >
          <p className="text-sm font-semibold" style={{ color: T.inkStrong }}>
            บัญชีนี้ไม่มีสิทธิ์เข้าถึงหน้าแอดมิน
          </p>
          <button
            onClick={() => {
              handleLogout();
              window.location.href = "/";
            }}
            className="rounded-full px-4 py-2.5 text-sm font-bold text-white"
            style={{ background: T.pinkHeart }}
          >
            กลับหน้าเว็บปกติ
          </button>
        </div>
      );
    }

    return <AdminDashboard onLogout={handleLogout} />;
  }

  // ไม่ได้อยู่ที่ /admin - หน้าเว็บปกติสำหรับลูกค้าทั่วไป ไม่มีร่องรอยของโหมดแอดมินอยู่บนหน้านี้เลย
  return <UserApp key={catalogKey} />;
}
